 private static PlayerSnapshot V(GameEngine g,int s)=>g.CreateSnapshot(s).Players[s];
 private static PendingDecision? P(GameEngine g)=>Enumerable.Range(0,4).Select(s=>g.CreateSnapshot(s).PendingDecision).FirstOrDefault(p=>p is not null);
 private static T[] E<T>(GameEngine g)where T:IGameEvent=>g.Events.Select(e=>e.Payload).OfType<T>().ToArray();
 private static CaoYuReceipt? Current(GameEngine g)=>g.ResolutionStack.OfType<ProgramSkillFrame>().LastOrDefault(f=>f.CaoYu is not null)?.CaoYu;
 private static string? Branch(PromptChoice c)=>c.Parameters.GetValueOrDefault("branch");
 private static bool Optional(GameEngine g,string skill)=>P(g)is{PlayerSeat:0}p&&(p.SkillPrompt?.SkillId==skill&&p.Choices.Any(c=>c.Parameters.GetValueOrDefault("program-action")=="activate")||p.Kind==DecisionKind.RescueDying&&p.Choices.Any(c=>c.Parameters.GetValueOrDefault("response")=="program-trigger"&&c.Parameters.GetValueOrDefault("skill-id")==skill));
 private static void Need(bool yes,string why){if(!yes)throw new InvalidOperationException("scene="+Scene+" "+why);}
 private static void Accept(GameEngine g,GameCommand c){try{var x=g.Submit(CommandJson.Deserialize(CommandJson.Serialize([c])).Single());Need(x.Accepted,x.Error?.Message??"Rejected real CaoYu command.");}catch(Exception e){throw new InvalidOperationException("scene="+Scene+" command="+c.GetType().Name+" cause="+e.Message+" "+Diagnostic(g),e);}}
 private static void Answer(GameEngine g,Func<PromptChoice,bool> match){var p=P(g)!;var c=p.Choices.FirstOrDefault(match);Need(V(g,p.PlayerSeat).IsHuman&&c is not null,"Missing actual human choice: "+Diagnostic(g));Accept(g,new AnswerPromptCommand(p.PlayerSeat,p.PromptId,c!.Id,g.Revision));}
 private static void Pick(GameEngine g,string branch,int[]? targets=null,int[]? cards=null)=>Answer(g,c=>Branch(c)==branch&&(targets is null||c.Targets.SequenceEqual(targets))&&(cards is null||c.Cards.SequenceEqual(cards)));
 private static void Activate(GameEngine g,string skill){Reach(g,()=>Optional(g,skill));Answer(g,c=>c.Parameters.GetValueOrDefault("program-action")=="activate"||c.Parameters.GetValueOrDefault("response")=="program-trigger"&&c.Parameters.GetValueOrDefault("skill-id")==skill);}
 private static void Use(GameEngine g,string id,int[]? cards=null,int[]? targets=null)=>Accept(g,new UseProgramSkillCommand(0,Driver,id,cards??[],targets??[],g.Revision,P(g)!.PromptId));
 private static void NativeEquip(GameEngine g){var a=g.GetHumanLegalActions().First(a=>a.Kind==LegalActionKind.Equip);Accept(g,new PlayCardCommand(0,a.CardId!.Value,a.TargetSeats,g.Revision,P(g)!.PromptId,a.PlayedCardKind,a.TargetCardId){ConversionSource=a.ConversionSource,AdditionalConversionSources=a.AdditionalConversionSources??[]});}
 private static void End(GameEngine g)=>Accept(g,new EndPlayPhaseCommand(0,g.Revision,P(g)!.PromptId));
 private static void Play(GameEngine g)=>Reach(g,()=>P(g)is{PlayerSeat:0,Kind:DecisionKind.PlayCard});
 private static void Reach(GameEngine g,Func<bool> done,[CallerMemberName]string caller="",[CallerLineNumber]int line=0)
 {
  for(var i=0;i<360;i++)
  {if(done())return;Need(g.State.Winner==Winner.None,$"Ended {caller}:{line}: "+Diagnostic(g));var p=P(g);if(p is null||!V(g,p.PlayerSeat).IsHuman){Accept(g,new AdvanceOneStepCommand(g.Revision));continue;}if(p.Kind==DecisionKind.PlayCard)End(g);else if(Current(g)is{Stage:CaoYuStage.XiangxuChoice})Pick(g,"decline");else if(p.Kind is DecisionKind.RespondDodge or DecisionKind.RespondSlash or DecisionKind.Nullification)Answer(g,c=>c.Cards.Count==0);else if(p.Kind==DecisionKind.RescueDying)Answer(g,c=>c.Parameters.GetValueOrDefault("response")is"let-die"or"pass");else if(p.Choices.Any(c=>c.Parameters.GetValueOrDefault("program-action")=="skip"))Answer(g,c=>c.Parameters.GetValueOrDefault("program-action")=="skip");else if(p.Choices.Any(c=>c.Parameters.GetValueOrDefault("option-id")=="continue"))Answer(g,c=>c.Parameters.GetValueOrDefault("option-id")=="continue");else throw new InvalidOperationException($"Unexpected {caller}:{line}: "+Diagnostic(g));}throw new InvalidOperationException($"Missing bounded {caller}:{line}: "+Diagnostic(g));
 }
 private static string Diagnostic(GameEngine g)=>JsonSerializer.Serialize(new{Scene,g.State.TurnNumber,g.State.CurrentSeat,g.State.Phase,Players=Enumerable.Range(0,4).Select(s=>new{Seat=s,V(g,s).GeneralId,V(g,s).Hp,V(g,s).MaxHp,V(g,s).HandCount,V(g,s).IsAlive}),Prompt=P(g)is{}p?new{p.PlayerSeat,p.Kind,Skill=p.SkillPrompt?.SkillId,Choices=p.Choices.Take(5).Select(c=>new{c.Cards,c.Targets,c.Parameters})}:null,Frames=g.ResolutionStack.TakeLast(5).Select(f=>new{f.Id,Type=f.GetType().Name,Stage=(f as ProgramSkillFrame)?.CaoYu?.Stage,Index=(f as ProgramSkillFrame)?.InstructionIndex}),Facts=g.Events.TakeLast(3).Select(e=>e.Payload.ToString())});
 private static string State(GameEngine g)=>JsonSerializer.Serialize(new{Views=Enumerable.Range(0,4).Select(s=>SnapshotJson.Serialize(g.CreateSnapshot(s))),Frames=g.ResolutionStack.Select(f=>JsonSerializer.Serialize(f,f.GetType())),Events=g.Events.Select(e=>JsonSerializer.Serialize(e.Payload,e.Payload.GetType())),g.CardMovements,Zones=g.CreateCardZoneDiagnostics(),Commands=CommandJson.Serialize(g.AcceptedCommands)});
 private static GameEngine Cold(GameEngine g,ContentRegistry r){var cold=GameReplay.Restore(GameCheckpointJson.Deserialize(GameCheckpointJson.Serialize(g.CreateCheckpoint())),r);Need(State(g)==State(cold),"Cold replay preserves every private opaque choice, causal minimum vector, independent ending source/instance, permanent history, actual dying frame and once-paid native child.");return cold;}
